/*!50003 CREATE*/ /*!50017 DEFINER=`baleeed5_wellness`@`localhost`*/ /*!50003 TRIGGER `trg_up_report_table` AFTER UPDATE ON `activity_table` FOR EACH ROW 
BEGIN
    DECLARE ExpectedDisciplineDays INT DEFAULT 5;
    DECLARE EducatedCount INT DEFAULT 0;
    DECLARE BreakfastedCount INT DEFAULT 0;
    DECLARE LunchedCount INT DEFAULT 0;
    DECLARE DinnedCount INT DEFAULT 0;
    DECLARE WeightedCount INT DEFAULT 0;
    DECLARE activity_discipline_percentage DECIMAL(5, 2) DEFAULT 0.00;
    DECLARE TotalActivityCount INT DEFAULT 0;
    DECLARE TotalDays INT DEFAULT 0;
    DECLARE overall_activity_discipline_percentage DECIMAL(5, 2) DEFAULT 0.00;

    -- Calculate activity counts
    SELECT COUNT(*)
    INTO EducatedCount
    FROM activity_table AS a
    INNER JOIN discipline_table AS d
    ON a.EntryDate >= d.ValidityStartDate
    AND a.EntryDate <= d.ValidityEndDate
    AND d.Activity = 'Education'
    WHERE a.ActivityName = 'Education'
    AND TIME(a.PostedDateTime) BETWEEN d.ActivityStartTime AND d.ActivityEndTime
    AND a.Validity = 1
    AND a.EntryUser = NEW.EntryUser;

    SELECT COUNT(*)
    INTO BreakfastedCount
    FROM activity_table
    WHERE ActivityName = 'Breakfast'
    AND TIME(PostedDateTime) BETWEEN '05:00:00' AND '08:30:59'
    AND Validity = 1
    AND EntryUser = NEW.EntryUser;

    SELECT COUNT(*)
    INTO LunchedCount
    FROM activity_table
    WHERE ActivityName = 'Lunch'
    AND TIME(PostedDateTime) BETWEEN '12:00:00' AND '14:00:59'
    AND Validity = 1
    AND EntryUser = NEW.EntryUser;

    SELECT COUNT(*)
    INTO DinnedCount
    FROM activity_table
    WHERE ActivityName = 'Dinner'
    AND TIME(PostedDateTime) BETWEEN '17:30:00' AND '20:30:59'
    AND Validity = 1
    AND EntryUser = NEW.EntryUser;

    SELECT COUNT(*)
    INTO WeightedCount
    FROM data_table
    WHERE ActivityName = 'Weight'
    AND TIME(PostedDateTime) BETWEEN '03:00:00' AND '06:00:59'
    AND Validity = 1
    AND EntryUser = NEW.EntryUser;

    -- Calculate the total number of days from the start of activities to the current date
    SELECT DATEDIFF(CURDATE(), MIN(EntryDate)) + 1
    INTO TotalDays
    FROM activity_table
    WHERE EntryUser = NEW.EntryUser;

    -- Calculate the activity discipline percentage
    SET activity_discipline_percentage = ((EducatedCount + BreakfastedCount + LunchedCount + DinnedCount + WeightedCount) / ExpectedDisciplineDays) * 100;
    
    -- Calculate total activity counts up to the current date
    SELECT COUNT(*)
    INTO TotalActivityCount
    FROM activity_table
    WHERE ActivityName IN ('Education', 'Breakfast', 'Lunch', 'Dinner')
    AND Validity = 1
    AND EntryUser = NEW.EntryUser;

    SET TotalActivityCount = TotalActivityCount + (
        SELECT COUNT(*)
        FROM data_table
        WHERE ActivityName = 'Weight'
        AND Validity = 1
        AND EntryUser = NEW.EntryUser
    );

    -- Calculate the overall activity discipline percentage
    SET overall_activity_discipline_percentage = (TotalActivityCount / (TotalDays * ExpectedDisciplineDays)) * 100;

    -- Update the result in the database
    UPDATE report_table
    SET `Over All Discipline%` = ROUND(overall_activity_discipline_percentage, 2)
    WHERE Members = NEW.EntryUser;

END */;;
DELIMITER ;
